using System.Collections.Generic;
using UnityEngine;

namespace CarX.Level
{
    /// <summary>Trash of one tunnel line, room or chamber, generated by the "Мусор" tool from the graph data
    /// (count + seed). Rebuilt when the tunnel changes: do not edit the children by hand, put hand-placed props into "Props".
    /// The trash has no colliders: walking through it is caught by <see cref="TrashSteps"/> using the step boxes below.</summary>
    [DisallowMultipleComponent, AddComponentMenu("")]
    public class TunnelTrashGroup : MonoBehaviour
    {
        public string owner;
        public int signature;
        public int items;
        [Tooltip("Зоны шагов по мусору (в координатах этой группы)")]
        public List<TrashStepBox> steps = new List<TrashStepBox>();

        void OnEnable() { if (Application.isPlaying) TrashSteps.Register(this); }
        void OnDisable() { TrashSteps.Unregister(this); }

        /// <summary>The step box containing a world point, or -1.</summary>
        public int BoxAt(Vector3 world)
        {
            var p = transform.InverseTransformPoint(world);
            for (int i = 0; i < steps.Count; i++)
            {
                var b = steps[i];
                var q = Quaternion.Inverse(b.rotation) * (p - b.center);
                if (Mathf.Abs(q.x) <= b.size.x * 0.5f && Mathf.Abs(q.y) <= b.size.y * 0.5f && Mathf.Abs(q.z) <= b.size.z * 0.5f) return i;
            }
            return -1;
        }

        void OnDrawGizmosSelected()
        {
            foreach (var b in steps)
            {
                Gizmos.matrix = transform.localToWorldMatrix * Matrix4x4.TRS(b.center, b.rotation, Vector3.one);
                Gizmos.color = b.kind == TrashKind.Litter ? new Color(1f, 0.9f, 0.3f, 0.8f) : new Color(1f, 0.5f, 0.1f, 0.8f);
                Gizmos.DrawWireCube(Vector3.zero, b.size);
            }
            Gizmos.matrix = Matrix4x4.identity;
        }
    }
}
